"""
Auto-generate engine.pyi type stubs from the compiled Rust `engine` module.

Usage:
    python gen_stubs.py
"""

import inspect
from pathlib import Path


def generate_stubs():
    try:
        import engine
    except ImportError:
        print("Error: Could not import 'engine'. Did you run 'maturin develop' first?")
        return

    output_path = Path(__file__).parent / "engine.pyi"
    lines = [
        '"""Type stubs for the compiled Rust engine extension.',
        "",
        "Auto-generated by gen_stubs.py. Do not edit manually.",
        '"""',
        "",
        "from collections.abc import Sequence",
        "",
    ]

    for name, obj in inspect.getmembers(engine):
        if name.startswith("_"):
            continue
        if inspect.isroutine(obj):
            try:
                sig = inspect.signature(obj)
            except (ValueError, TypeError):
                sig = "(...)"

            doc = inspect.getdoc(obj)
            lines.append(f"def {name}{sig}:")
            if doc:
                lines.append('    """')
                for doc_line in doc.splitlines():
                    lines.append(f"    {doc_line}" if doc_line else "")
                lines.append('    """')
            lines.append("    ...\n")

    output_path.write_text("\n".join(lines), encoding="utf-8")
    print(f"Successfully generated stubs at: {output_path}")


if __name__ == "__main__":
    generate_stubs()
